import pygamefrom random import choicefrom collections import dequeclass Grid:    BACKGROUND_COLORS = [(166, 209, 60), (173, 214, 68)]    def __init__(self, screen_size, size=18):        self.SIZE = size        self.SQUARE_SIZE = screen_size // self.SIZE        self.matrix = [[0 for _ in range(self.SIZE)] for _ in range(self.SIZE)]        self.previous_matrix = [[-1 for _ in range(self.SIZE)] for _ in range(self.SIZE)]        self.empty_cells = {(i, j)for i in range(self.SIZE) for j in range(self.SIZE)}        self.rectangles = self.create_rectangles()    def create_rectangles(self):        rectangles = []        for i in range(self.SIZE):            rectangle_row = []            for j in range(self.SIZE):                rectangle_row.append(pygame.rect.Rect(self.SQUARE_SIZE*j, self.SQUARE_SIZE*i,                                                      self.SQUARE_SIZE, self.SQUARE_SIZE))            rectangles.append(rectangle_row)        return rectangles    def update_cell(self, row, column, value):        self.matrix[row][column] = value        if value == 0:            self.empty_cells.add((row, column))        else:            self.empty_cells.discard((row, column))    def draw(self):        updated_rectangles = []        for i in range(self.SIZE):            for j in range(self.SIZE):                if self.previous_matrix[i][j] == self.matrix[i][j]:                    continue                content = self.matrix[i][j]                rectangle = self.rectangles[i][j]                if (color_index := i%2 + j%2) > 1:                    color_index = 0                color = self.BACKGROUND_COLORS[color_index]                pygame.draw.rect(screen, color, rectangle)                if content == 15:                    screen.blit(FOOD_SPRITE, rectangle)                elif content > 0:                    sprite = SNAKE_SPRITES[content-1]                    screen.blit(sprite, rectangle)                updated_rectangles.append(rectangle)        self.previous_matrix = [row[:] for row in self.matrix]        return updated_rectanglesclass SnakeBodyCell:    def __init__(self, pos, direction):        self.row = pos[0]        self.column = pos[1]        self.direction = directionclass Snake:    DIRECTION_MAP = {        ('right', 'up'): 10, ('right', 'down'): 8, ('left', 'up'): 9, ('left', 'down'): 7,        ('up', 'right'): 7, ('up', 'left'): 8, ('down', 'right'): 9, ('down', 'left'): 10,        ('left', 'left'): 5, ('right', 'right'): 5, ('up', 'up'): 6, ('down', 'down'): 6    }    def __init__(self, grid, direction='right'):        self.grid = grid        self.head_pos = self.grid.SIZE // 2        self.head_pos = (self.head_pos, self.head_pos)        tail_pos = (self.head_pos[0], self.head_pos[1]-1)        self.body = deque(maxlen=self.grid.SIZE ** 2)        self.body.append(SnakeBodyCell(self.head_pos, direction))        self.body.append(SnakeBodyCell(tail_pos, direction))        self.size = 2        self.grid.update_cell(self.head_pos[0], self.head_pos[1], 1)        self.grid.update_cell(tail_pos[0], tail_pos[1], 11)    def next_pos(self, direction):        row, column = self.head_pos        if direction == 'right':            return row, column + 1        elif direction == 'left':            return row, column - 1        elif direction == 'up':            return row - 1, column        elif direction == 'down':            return row + 1, column    def new_head(self, direction):        previous_head = self.body[0]        self.grid.update_cell(self.head_pos[0], self.head_pos[1], DIRECTIONS_INDEX[direction])        self.body.appendleft(SnakeBodyCell(self.head_pos, direction))        if self.size < 3:            return        self.grid.update_cell(previous_head.row, previous_head.column, self.DIRECTION_MAP[previous_head.direction, direction])    def move(self, direction):        self.head_pos = self.next_pos(direction)        self.new_head(direction)        tail = self.body.pop()        self.grid.update_cell(tail.row, tail.column, 0)        tail = self.body[-1]        tail_direction = self.body[-2].direction        self.grid.matrix[tail.row][tail.column] = 10 + DIRECTIONS_INDEX[tail_direction]    def grow(self, pos, direction):        self.head_pos = pos        self.size += 1        self.new_head(direction)    def kill(self):        for cell in self.body:            self.grid.matrix[cell.row][cell.column] = 0class Food:    def __init__(self, grid):        self.row, self.column = choice(tuple(grid.empty_cells))        grid.matrix[self.row][self.column] = 15class Game:    def __init__(self, screen_size):        self.grid = Grid(screen_size)        self.snake = Snake(self.grid)        self.food = Food(self.grid)        self.direction = 'right'        self.previous_direction = 'right'        self.prev_time = pygame.time.get_ticks()        self.counter = 0    def collision(self, direction):        next_row, next_column = self.snake.next_pos(direction)        if next_row < 0 or next_row > self.grid.SIZE-1 or next_column < 0 or next_column > self.grid.SIZE-1:            self.snake.kill()            self.snake = Snake(self.grid)            self.direction = 'right'            self.previous_direction = 'right'            return True        elif next_row == self.food.row and next_column == self.food.column:            self.food = Food(self.grid)            self.snake.grow((next_row, next_column), direction)            return True        elif self.grid.matrix[next_row][next_column] != 0:            self.snake.kill()            self.snake = Snake(self.grid)            self.direction = 'right'            self.previous_direction = 'right'            return True        return False    def move(self):        sum_directions = DIRECTIONS_INDEX[self.direction] + DIRECTIONS_INDEX[self.previous_direction]        if sum_directions == 3 or sum_directions == 7:            self.direction = self.previous_direction        if not self.collision(self.direction):            self.snake.move(self.direction)        self.previous_direction = self.direction    def update(self):        now = pygame.time.get_ticks()        self.counter += now - self.prev_time        self.prev_time = now        if self.counter > 200:            game.move()            self.counter = 0    def draw(self):        updated_rectangles = self.grid.draw()        pygame.display.update(updated_rectangles)SCREEN_SIZE = 720pygame.init()screen = pygame.display.set_mode((SCREEN_SIZE, SCREEN_SIZE))clock = pygame.Clock()SNAKE_SPRITES = [pygame.image.load('sprites/head_right.png').convert_alpha(),                 pygame.image.load('sprites/head_left.png').convert_alpha(),                 pygame.image.load('sprites/head_up.png').convert_alpha(),                 pygame.image.load('sprites/head_down.png').convert_alpha(),                 pygame.image.load('sprites/body_horizontal.png').convert_alpha(),                 pygame.image.load('sprites/body_vertical.png').convert_alpha(),                 pygame.image.load('sprites/body_topright.png').convert_alpha(),                 pygame.image.load('sprites/body_topleft.png').convert_alpha(),                 pygame.image.load('sprites/body_bottomright.png').convert_alpha(),                 pygame.image.load('sprites/body_bottomleft.png').convert_alpha(),                 pygame.image.load('sprites/tail_right.png').convert_alpha(),                 pygame.image.load('sprites/tail_left.png').convert_alpha(),                 pygame.image.load('sprites/tail_up.png').convert_alpha(),                 pygame.image.load('sprites/tail_down.png').convert_alpha()]FOOD_SPRITE = pygame.image.load('sprites/apple.png').convert_alpha()DIRECTIONS_INDEX = {'right': 1, 'left': 2, 'up': 3, 'down': 4}game = Game(SCREEN_SIZE)running = Truewhile running:    for event in pygame.event.get():        if event.type == pygame.QUIT:            running = False        elif event.type == pygame.KEYDOWN:            if event.key == pygame.K_d or event.key == pygame.K_RIGHT:                game.direction = 'right'            elif event.key == pygame.K_a or event.key == pygame.K_LEFT:                game.direction = 'left'            elif event.key == pygame.K_w or event.key == pygame.K_UP:                game.direction = 'up'            elif event.key == pygame.K_s or event.key == pygame.K_DOWN:                game.direction = 'down'    game.update()    game.draw()    clock.tick(60)